7745: /** @brief attach 之前 root 已有的子对象数（地铁画布等外来件个数，重建时保留）。 */
7746: static uint8_t s_build_keep_n;
7747: 
7748: /** @brief 换主题后用：本层重建一遍（颜色是建页时烘进样式的）。
7749:  *
7750:  *  @details `helm_color()` 的值写在 `lv_obj_set_style_*` 那一刻 ⇒ 换主题只
7751:  *           `lv_obj_invalidate()` 只是"把旧样子重画一遍"，必须**重建对象**才能重新
7752:  *           取值。菜单那边靠 `helm_menu_paint()` 重建行，本层靠这里。
7753:  *
7754:  *  @note 只删**本层自己建**的对象（`helm_shell_attach()` 里打过 LV_OBJ_FLAG_USER_2
7755:  *        标记的）；地图画布等外来件（vmap 建的兄弟节点）必须留着 —— 待机 pane 的
7756:  *        注释里记着"地图画布从没被绘制过"那次花屏的教训。 */
7757: /** @brief 重入保护：本函数正在重建时，内层再进来直接返回。
7758:  *
7759:  *  @details 2026-09-26 上板实测：把 `helm_shell_rebuild()` 接进换主题通知后，
7760:  *           **一次切换就把 UI 卡死**（log 停住、无 panic/assert = 硬挂）。
7761:  *           机制是重入：重建走 `helm_shell_attach()` → 各 builder →
7762:  *           其中有 `map_page_set_map_ui_visible()` 一类会**再触发一次主题通知**，
7763:  *           于是内层又一次进来删对象 —— **删的正是外层正在遍历的子对象**，
7764:  *           链表当场错乱。所以保护的不是"重复做功"，是**外层的遍历**。
7765:  *  @note 内层返回后外层照常跑完，本轮重建仍然生效（不是"跳过"）。 */
7766: static bool s_rebuilding;
7767: 
7768: static void helm_shell_rebuild_once(void)
7769: {
7770:     map_page_t * map = s_sh.map;
7771:     lv_obj_t * root;
7772:     uint32_t i;
7773: 
7774:     if (map == NULL || !s_sh.attached) {
7775:         return;
7776:     }
7777: 
7778:     root = map_page_root(map);
7779:     if (root == NULL) {
7780:         return;
7781:     }
7782: 
7783:     /* 换主题才走这里 ⇒ 打点不心疼：真卡住时"最后一行"就是现场（这一族踩过两次）。 */
7784:     syslog(LOG_WARNING, "[theme] delete begin n=%u",
7785:            (unsigned)lv_obj_get_child_count(root));
7786: 
7787:     for (i = lv_obj_get_child_count(root); i > 0u; i--) {
7788:         lv_obj_t * c = lv_obj_get_child(root, i - 1u);
7789: 
7790:         if (c != NULL && lv_obj_has_flag(c, LV_OBJ_FLAG_USER_2)) {
7791:             lv_obj_delete(c);
7792:         }
7793:     }
7794: 
7795:     syslog(LOG_WARNING, "[theme] delete done");
7796: 
7797:     s_sh.attached = false;
7798:     helm_shell_attach(map);        /* 按开机顺序重建 */
7799:     syslog(LOG_WARNING, "[theme] attach done");
7800:     helm_apply_view();             /* 恢复当前页 */
7801:     syslog(LOG_WARNING, "[theme] view done");
7802: 
7803:     /*
7804:      * 重建把上一轮入场动画的对象一起删了（`lv_obj_delete` 会清掉挂在对象上的
7805:      * 动画），新控件默认全不透明 ⇒ 若此时首轮错峰还在跑，看起来就是"第三组被砍断、
7806:      * 新控件直接全显"。重建发生在主界面且转场已结束（见 `helm_shell_theme_apply`），
7807:      * 正好是重播一次入场的时机；两处触发都幂等，不会叠出两轮。
7808:      */
7809:     helm_shell_enter_anim();
7810: }
7811: 
7812: void helm_shell_rebuild(void)
7813: {
7814:     if (s_rebuilding) {
7815:         return;                    /* 内层重入：见 s_rebuilding 的注释，这里是防挂的关键 */
7816:     }
7817: 
7818:     s_rebuilding = true;
7819:     helm_shell_rebuild_once();
7820:     s_rebuilding = false;
7821: 
7822:     /*
7823:      * ⚠ 换主题后的"剖面重烘焙"必须登记在**重建之后**（对象是新的）：绘制路径拿到这个标志
7824:      * 会用既有数据 `helm_climb_canvas_bake()` 重烘；若重建把剖面数据也清了（日志里的
7825:      * `[theme] hist_reset`），bake() 返回假 ⇒ 走正常 reload 重新取数再烘 —— 两条路都不会
7826:      * 留下空白，也不会烘在已被删除的对象上（2026-09-27 打桩定位到的顺序问题）。
7827:      */
7828:     s_climb_rebake = true;
7829: 
7830:     /*
7831:      * ⚠ 还要作废**剖面指纹**：`s_climb_eles[]`（每点海拔）与 `s_climb_zone[]`（坡度分段）
7832:      * 是静态缓存，它们的重算被"点数 / 总里程"指纹挡着 —— 而**重建不等于指纹变化**
7833:      * （点数、总里程都没变）⇒ 重建把数组清掉后重算会被跳过 ⇒ 烘焙出来的折线是空的。
7834:      */
7835:     s_climb_fp_pts = 0xffffffffu;
7836:     s_climb_fp_total_cm = 0xffffffffu;
7837:     s_climb_fp_rec_n = 0xff;
7838:     s_climb_fp_rec_slot = 0xffffffffu;
7839: }
