7859: /** @brief 待办的主界面重建：**只在地图页是当前页时**执行，否则继续等。
7860:  *
7861:  *  @details 2026-09-26 上板实测（这是本函数存在的全部理由）：
7862:  *           在**菜单页开着**的时候重建地图页那一层，会把菜单页弄死 —— 表现是
7863:  *           菜单按键回调一律 0ms 返回（= `s_menu == NULL`，菜单页被关掉/状态被释放），
7864:  *           画面停在换色后的那一帧不再更新，而主界面（此时才是真正的当前页）一切正常；
7865:  *           对照实验：只跑 ①②（不动这一层）菜单全程活着，接回 ③ 就复现。
7866:  *           而**地图页可见时**重建是好的（实测：连续切换后菜单仍能正常翻行）。
7867:  *           ⇒ 规则：这一层重建只在该页为当前页时做；不在地图页就挂着，
7868:  *             等主循环下一次问的时候（= 用户回到主界面）再重建 —— 这也正是
7869:  *             "颜色要重新取"的那一刻，用户看到的就是重建后的新配色。 */
7870: void helm_shell_theme_apply(void)
7871: {
7872:     if (!s_theme_rebuild_pending) {
7873:         return;
7874:     }
7875: 
7876:     if (lvgl_page_current_id() != (int)BICYCLE_PM_ID_MAP ||
7877:         lvgl_page_nav_busy()) {
7878:         return;                    /* 不在主界面/转场还没走完 ⇒ 等（见上） */
7879:     }
7880: 
7881:     s_theme_rebuild_pending = false;
7882:     helm_shell_rebuild();
7883: }
