44:     lv_anim_set_var(&a, obj);
45:     lv_anim_set_values(&a, from, to);
46:     lv_anim_set_duration(&a, ms);
47:     lv_anim_set_path_cb(&a, (path != NULL) ? path : lv_anim_path_ease_out);
48:     lv_anim_set_exec_cb(&a, exec);
49:     if (done != NULL) {
50:         lv_anim_set_completed_cb(&a, done);
51:     }
52:     lv_anim_start(&a);
53: }
